// Builds the frame that carries a message, as docs/PROTOCOL.md describes under Framing. Returns a Buffer.
export function encodeFrame(payload) {
  const body = Buffer.from(JSON.stringify(payload), 'utf8')
  let checksum = 0
  for (const byte of body) checksum ^= byte
  const header = Buffer.from([0x45, 0x4e, 0x43, 0x37, 3, 0, 0])
  header.writeUInt16BE(body.length, 5)
  return Buffer.concat([header, body, Buffer.from([checksum])])
}
